#include <vector>
#include <omp.h>

/* Return the product of the vector x with every odd indexed element inverted:
   x_0 * (1/x_1) * x_2 * (1/x_3) * ….
   The algorithm is written so that the result is deterministic for any
   number of OpenMP threads (no race conditions, no order‑dependent reductions). */
double productWithInverses(const std::vector<double>& x) {
    // Determine an upper bound on the number of threads that may be used.
    const int max_threads = omp_get_max_threads();

    // One slot per thread to hold its private partial product.
    std::vector<double> thread_prod(max_threads, 1.0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();   // unique thread id
        double local = 1.0;                     // thread‑local accumulator

        // Distribute the work; each thread multiplies the terms it owns.
        #pragma omp for schedule(static)
        for (std::size_t i = 0; i < x.size(); ++i) {
            double term = (i % 2 == 0) ? x[i] : 1.0 / x[i];
            local *= term;
        }

        // Store the thread's partial result in a location unique to this thread.
        thread_prod[tid] = local;
    }

    // Combine the per‑thread partial products in a fixed (thread‑id) order.
    double result = 1.0;
    for (int i = 0; i < max_threads; ++i) {
        result *= thread_prod[i];
    }
    return result;
}
