/* Return the product of the vector x with every odd indexed element inverted:
   x_0 * (1/x_1) * x_2 * (1/x_3) * ….
   The implementation is deterministic for any number of OpenMP threads:
   - The computation of each factor is done in parallel.
   - The final multiplication is performed sequentially in the original index order,
     eliminating any order‑dependence of floating‑point reductions.
*/
double productWithInverses(const std::vector<double>& x) {
    const std::size_t n = x.size();
    if (n == 0) return 1.0;               // empty product

    // Step 1: compute each factor in parallel.
    std::vector<double> factor(n);
    #pragma omp parallel for schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        factor[i] = (i % 2 == 0) ? x[i] : 1.0 / x[i];
    }

    // Step 2: multiply factors sequentially in the original order.
    double result = 1.0;
    for (std::size_t i = 0; i < n; ++i) {
        result *= factor[i];
    }
    return result;
}
